import React, { useState } from "react";
import { startLiveBot } from "../services/api";

const LiveMeetingBot = () => {
  const [link, setLink] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(false);

  const handleStartBot = async () => {
    if (!link.trim()) {
      setError("Please enter a meeting link");
      return;
    }

    setLoading(true);
    setError(null);
    setSuccess(false);

    try {
      await startLiveBot(link);
      setSuccess(true);
      setLink("");
    } catch (err) {
      setError(err.response?.data?.error || "Failed to start bot");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="card">
      <h2>Live Meeting Bot</h2>
      <input
        type="text"
        placeholder="Enter meeting link (Google Meet or Zoom)"
        value={link}
        onChange={(e) => setLink(e.target.value)}
        style={{ width: "100%", padding: "8px", marginBottom: "10px" }}
      />
      {error && <p style={{ color: "red" }}>{error}</p>}
      {success && <p style={{ color: "green" }}>Bot started successfully!</p>}
      <button onClick={handleStartBot} disabled={loading}>
        {loading ? "Starting..." : "Join Meeting"}
      </button>
    </div>
  );
};

export default LiveMeetingBot;
